    /// <summary>Looks up a winget return code.</summary>
    /// <param name="hresult">HRESULT reported by winget.</param>
    /// <returns>The code, or <c>null</c> when winget does not define it.</returns>
    public static WingetErrorCode? Find(int hresult) =>
        Codes.TryGetValue(hresult, out WingetErrorCode? code) ? code : null;
